-- one table per concrete class, base columns duplicated, no table for the abstract base
CREATE TABLE engineers (id BIGINT PRIMARY KEY, name TEXT NOT NULL, salary REAL NOT NULL);
CREATE TABLE managers  (id BIGINT PRIMARY KEY, name TEXT NOT NULL, department TEXT NOT NULL);
-- keys come from one source so they stay unique across the hierarchy
CREATE SEQUENCE employee_key;
-- hierarchy-wide read: union with NULL padding and a synthesized tag
CREATE VIEW employees AS
  SELECT id, name, 'engineer' AS kind, salary, NULL AS department FROM engineers
  UNION ALL
  SELECT id, name, 'manager'  AS kind, NULL,   department FROM managers;
